import heapq, math

def astar_octile(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    blocked = lambda r, c: not (0 <= r < rows and 0 <= c < cols) or grid[r][c] == "#"
    def h(cell):
        dr, dc = abs(cell[0] - goal[0]), abs(cell[1] - goal[1])
        return max(dr, dc) + (math.sqrt(2) - 1) * min(dr, dc)
    g = {start: 0.0}
    heap = [(h(start), start)]
    closed = set()
    while heap:
        _, cell = heapq.heappop(heap)
        if cell in closed:
            continue
        if cell == goal:
            return g[cell]
        closed.add(cell)
        r, c = cell
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == dc == 0 or blocked(r + dr, c + dc):
                    continue
                if dr and dc and (blocked(r + dr, c) or blocked(r, c + dc)):
                    continue
                nd = g[cell] + (math.sqrt(2) if dr and dc else 1.0)
                if nd < g.get((r + dr, c + dc), math.inf):
                    g[(r + dr, c + dc)] = nd
                    heapq.heappush(heap, (nd + h((r + dr, c + dc)), (r + dr, c + dc)))
    return None

exercises.solution:
A* with a closed set; the octile heuristic is consistent, so a cell never needs reopening once closed.

```python
import heapq, math

def astar_octile(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    blocked = lambda r, c: not (0 <= r < rows and 0 <= c < cols) or grid[r][c] == "#"
    def h(cell):
        dr, dc = abs(cell[0] - goal[0]), abs(cell[1] - goal[1])
        return max(dr, dc) + (math.sqrt(2) - 1) * min(dr, dc)
    g = {start: 0.0}
    heap = [(h(start), start)]
    closed = set()
    while heap:
        _, cell = heapq.heappop(heap)
        if cell in closed:
            continue
        if cell == goal:
            return g[cell]
        closed.add(cell)
        r, c = cell
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == dc == 0 or blocked(r + dr, c + dc):
                    continue
                if dr and dc and (blocked(r + dr, c) or blocked(r, c + dc)):
                    continue
                nd = g[cell] + (math.sqrt(2) if dr and dc else 1.0)
                if nd < g.get((r + dr, c + dc), math.inf):
                    g[(r + dr, c + dc)] = nd
                    heapq.heappush(heap, (nd + h((r + dr, c + dc)), (r + dr, c + dc)))
    return None
```

In the test `corner`, the diagonal from the bottom-right cell to the top-left one would pass the corner of the occupied cell, so the answer is 2 (two side steps), not $\sqrt 2$. In `post`, the wall forces the path over the top, and the corner rule forbids the diagonals that would graze the wall's ends, giving $3 + 2\sqrt 2$.
